let portraitFrame=null;
function animateHudPortraits(){
  if(portraitFrame!==null||!root||root.hidden||document.body.classList.contains("reduced-motion")||!root.querySelector(".one-hud-animated-avatar"))return;
  const draw=()=>{
    portraitFrame=null;
    if(!root||root.hidden||document.body.classList.contains("reduced-motion"))return;
    const canvases=root.querySelectorAll(".one-hud-animated-avatar");
    if(!canvases.length)return;
    const now=performance.now();
    for(const canvas of canvases){
      if(canvas.closest("[hidden]"))continue;
      const ctx=canvas.getContext("2d");
      if(!ctx)continue;
      ctx.clearRect(0,0,canvas.width,canvas.height);
      const character=canvas.avatarCharacter;
      drawPixelAvatar(ctx,character?.appearance||character||{},{size:64,equipment:character?.equipped,time:now,action:avatarAction(character),emotion:avatarEmotion(character)});
    }
    portraitFrame=requestAnimationFrame(draw);
  };
  portraitFrame=requestAnimationFrame(draw);
}
export function setHudVisible(visible){if(root)root.hidden=!visible;if(!visible){closePanel();if(portraitFrame!==null){cancelAnimationFrame(portraitFrame);portraitFrame=null}}else animateHudPortraits()}
export function initHud(){
  if(root)return;
  const style=document.createElement("style");style.textContent=STYLE;document.head.append(style);
  root=document.createElement("div");root.id="one-hud";
  root.style.setProperty("--color-ocean",PALETTE.ocean);root.style.setProperty("--color-panel",PALETTE.panel);root.style.setProperty("--color-gold",PALETTE.gold);
  root.innerHTML=`<header id="hud-header" class="one-hud-brand"><div class="one-hud-brand-copy"><span class="one-hud-clock" data-hud-day>Día 1 · 00:00 · 1:4</span><span class="one-hud-count" data-hud-berries>฿ 0</span><span class="one-hud-captain" data-hud-faction>Pirata</span></div></header><div class="one-hud-vitals" aria-label="Estado del avatar"><progress data-vital="health" max="100" value="100" aria-label="Salud"></progress><progress data-vital="experience" max="100" value="0" aria-label="Experiencia para el siguiente nivel"></progress></div><button class="one-hud-settings" type="button" data-hud-panel="more" aria-label="Ajustes y Panel Admin GM" title="Ajustes y Panel Admin GM">⚙️</button><div class="one-hud-toast" data-hud-toast role="status" hidden></div><div class="one-hud-controls" role="group" aria-label="Zoom del globo"><button class="one-hud-zoom" type="button" data-map-zoom="in" aria-label="Acercar globo">+</button><button class="one-hud-zoom" type="button" data-map-zoom="out" aria-label="Alejar globo">−</button></div><nav id="bottom-nav" class="one-hud-nav" aria-label="Navegación del juego">${[["news","Diario / Noticias"],["navigation","Navegación / Isla"],["tavern","Taberna"],["ship","Barco / Perfil"]].map(([key,label])=>`<button type="button" data-hud-panel="${key}" aria-expanded="false"><span class="one-hud-nav-icon">${svgIcon(ACTIONS[key][0])}</span><span>${label}</span></button>`).join("")}</nav><div class="one-hud-backdrop" aria-hidden="true"><section class="one-hud-dialog" role="dialog" aria-modal="true" aria-labelledby="hud-dialog-title"><div class="one-hud-heading"><span id="hud-dialog-title" class="one-hud-heading-title"></span><button class="one-hud-close" type="button" aria-label="Cerrar">✕</button></div><div class="one-hud-content"></div></section></div>`;
  document.body.append(root);
  root.querySelectorAll("[data-hud-panel]").forEach(button=>button.addEventListener("click",()=>{const key=button.dataset.hudPanel;if(key==="navigation"){if(currentPanel)closePanel();const c=activeCharacter;if(!c)return;if(c.location?.atSea){if(getCameraState()===ISLAND_VIEW)returnToGlobalMap(true);if(c.mapPosition)focusMap(c.mapPosition);else document.dispatchEvent(new CustomEvent("onepiece:map-fit"))}else showDockedIsland(c);return}openPanel(key==="tavern"?"chat":key==="ship"?"chest":key)}));
  root.querySelectorAll("[data-map-zoom]").forEach(button=>button.addEventListener("click",()=>document.dispatchEvent(new CustomEvent("onepiece:map-zoom",{detail:{direction:button.dataset.mapZoom==="in"?1:-1}}))));
  root.hidden=true;
  window.addEventListener("onepiece:block1-render",event=>{if(event.detail?.toast)showToast(event.detail.toast)});
  document.addEventListener("onepiece:systems-toast",event=>showToast(event.detail?.message));
  root.querySelector(".one-hud-close").addEventListener("click",()=>closePanel());
  root.querySelector(".one-hud-backdrop").addEventListener("click",event=>{if(event.target===event.currentTarget)closePanel()});
  document.addEventListener("keydown",event=>{if(event.key==="Escape")closePanel();if(event.altKey&&event.shiftKey&&event.code==="KeyG"){event.preventDefault();openPanel("adminGM")}});
  window.addEventListener("popstate",event=>{if(currentPanel&&event.state?.onepieceModal!==modalHistoryId)closePanel(true)});
}
export function renderHud(character){
  if(!root)initHud();
  activeCharacter=character;
  if(currentPanel==="adminGM"&&!isLocalGMAvailable(character))closePanel();
  document.body.classList.toggle("reduced-motion",Boolean(readJSON(STORAGE_KEYS.settings,{}).reducedMotion));
  const day=Number(character?.world?.day)||0,minute=Number(character?.world?.minuteOfDay)||0;
  root.querySelector("[data-hud-day]").textContent=`Día ${day+1} · ${String(Math.floor(minute/60)).padStart(2,"0")}:${String(minute%60).padStart(2,"0")} · 1:4`;
  root.querySelector("[data-hud-berries]").textContent=`฿ ${fmt(character?.berries)}`;
  root.querySelector("[data-hud-faction]").textContent=character?.faction||"Pirata";
  const wantedReward=root.querySelector(".one-hud-wanted-reward");
  if(wantedReward){if(Number(character?.bounty)>0)animateCount(wantedReward,character.bounty,(value)=>`฿ ${fmt(value)} BERRIES`);else{wantedReward.dataset.countTarget="0";wantedReward.textContent="SIN RECOMPENSA"}}
  root.hidden=!character;
  if(character){
    const health=root.querySelector('[data-vital="health"]');
    const experience=root.querySelector('[data-vital="experience"]');
    if(health){health.max=Math.max(1,Number(character.stats?.maxHealth)||100);health.value=Math.max(0,Number(character.stats?.health)||0)}
    if(experience){experience.max=Math.max(100,(Number(character.level)||1)*100);experience.value=Math.max(0,Number(character.experience)||0)}
    animateHudPortraits();
  }
  const hour=Math.floor(minute/60);root.dataset.atmosphere=character?.travel?.climate==="calm-belt"?"mist":hour>=19||hour<6?"night":"day";document.body.dataset.atmosphere=root.dataset.atmosphere;
  renderBranch(character);
  const writingChat=["chat","quick"].includes(currentPanel)&&[...root.querySelectorAll(".one-hud-content textarea")].some(input=>input.value.trim());
  if(!writingChat&&currentPanel&&["chat","quick","chest","boards","tavern","market","profile","codex","world","more","lineage","networkStatus","settings","adminGM"].includes(currentPanel))openPanel(currentPanel);
}
export function openIslandPanel(panel){
  if(!["chest","tavern","market","blackmarket"].includes(panel)||!activeCharacter)return;
  if(panel!=="chest"&&(activeCharacter.status==="dead"||activeCharacter.captured||activeCharacter.location?.atSea))return;
  if(panel==="blackmarket"&&!getMapIslands(activeCharacter).some(island=>island.name===activeCharacter.location?.island&&island.auctionHouse))return;
  openPanel(panel);
}
